import{_ as e,o,c as i,a2 as a}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Gemini 失败诊断与去廉价感","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-fail-diagnosis.md","filePath":"tools/gemini-fail-diagnosis.md","lastUpdated":1787714366000}'),d={name:"tools/gemini-fail-diagnosis.md"};function s(n,t,l,r,c,p){return o(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="gemini-失败诊断与去廉价感" tabindex="-1">Gemini 失败诊断与去廉价感 <a class="header-anchor" href="#gemini-失败诊断与去廉价感" aria-label="Permalink to &quot;Gemini 失败诊断与去廉价感&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源</p><ul><li>来源：Gemini Web（Google Gemini）现场问答</li><li>时间：2026-08-15</li><li>说明：本文为用户向 Gemini Web 提问拿到的回答，仅做排版整理，文字未做改写。内容由 Gemini 生成，未经 Google 官方文档逐一核实；涉及模型随机性、Seed 等行为请以实际测得的版本为准。</li></ul></div><blockquote><p>本组三个提问：</p><ol><li>同一句 prompt 每次生成差异很大，怎么判断是 prompt 的问题还是模型随机性？要改哪几处来收敛？</li><li>成片「廉价感」通常由哪几个因素造成（运镜太飘、打光平、材质假）？分别怎么在 prompt 里救？</li><li>一条 prompt 生成不满意时，有没有推荐的「诊断顺序」——先查时长、还是先查运镜、还是先查材质？迭代时每次只动一处吗？</li></ol></blockquote><h2 id="一、判断-是-prompt-问题还是模型随机性" tabindex="-1">一、判断：是 Prompt 问题还是模型随机性 <a class="header-anchor" href="#一、判断-是-prompt-问题还是模型随机性" aria-label="Permalink to &quot;一、判断：是 Prompt 问题还是模型随机性&quot;">​</a></h2><p>做一次「对照组测试」：保持 Prompt 绝对不变，连续生成 3–5 次。</p><ul><li><strong>是模型随机性</strong>：主体和核心构图基本一致（同一只碗、同一种色调、同样的微距视角），只有细节微抖（黄油融化的流动轨迹不同、酱汁沾染的斑点形状改变、光斑位置偏移）。—— Prompt 已发挥控制力，靠挑选满意版本（Cherry-picking）或固定 Seed 解决。</li><li><strong>是 Prompt 问题</strong>：每次生成的主体风格、画面结构或画质大相径庭（一次是二次元插画、一次是实拍；一次是俯拍全景、一次是微距特写；薯条的形状、包装袋风格完全不统一）。—— Prompt 缺乏排他性约束或关键锚点词，概率分布区间过大，模型在「猜」你的意图。</li></ul><p><strong>判定法则</strong>：核心主体形态（薯条规格、包装形态）、镜头轨迹（推/摇）、关键动作发生质变 → Prompt 描述层级太高、缺约束锚点；只变气泡、烟雾、撒料轨迹、光线微调 → 正常随机探索，无需大改。</p><h2 id="二、让生成收敛的-4-处修改" tabindex="-1">二、让生成收敛的 4 处修改 <a class="header-anchor" href="#二、让生成收敛的-4-处修改" aria-label="Permalink to &quot;二、让生成收敛的 4 处修改&quot;">​</a></h2><p>要把 Prompt 从「意境描述」改成「电影镜头指令 + 物理约束」，重点改这四处：</p><p><strong>1. 明确镜头语言与摄影参数</strong>（锁定视角与构图）</p><ul><li>不佳：<code>a close-up photo of french fries</code>（太宽泛）</li><li>收敛：<code>Extreme macro 85mm lens, shallow depth of field, 45-degree side angle</code>（限定了镜头、景深与角度）</li></ul><p><strong>2. 精细化材质与动态描述</strong>（锁定食欲感）</p><ul><li>不佳：<code>delicious honey butter fries, looks tasty</code></li><li>收敛：<code>Golden crispy french fries, glistening honey glaze, fine white butter powder dusting, steam gently rising in slow motion</code></li></ul><p><strong>3. 规范光影与色调</strong>（不同口味不同基调，避免随机匹配背景光）</p><ul><li>蜂蜜黄油味：<code>Warm studio lighting, golden hour rim light, high-key warm yellow tone</code></li><li>番茄味：<code>Vibrant cinematic lighting, rich crimson red background, bold high-contrast highlights</code></li></ul><p><strong>4. 固定词库结构</strong>（模板化）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[主体细节] + [环境/背景] + [摄影镜头/光影] + [动态/渲染质感]</span></span></code></pre></div><p><strong>实践范例（蜂蜜黄油薯条特写）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Extreme close-up shot of crispy golden-brown french fries. Fine melted butter coating and light powder specks on the surface. A slow-motion drizzle of translucent amber honey falling onto the fries. Studio macro photography, 105mm lens, soft backlight highlighting the honey translucency, warm yellow color palette. 4k resolution, commercial advertising style.</span></span></code></pre></div><p><strong>进阶收敛技巧</strong>：先出「高精度单帧图」再走图生视频（见 <a href="/tools/gemini-first-last-frame">首帧与首尾帧锁定</a>）；Negative Prompt 写 <code>blurry, distorted shape, cartoon, illustration, low resolution, extra noise</code>；能固定 Seed 就固定 Seed。</p><h2 id="三、廉价感四因素与救法" tabindex="-1">三、廉价感四因素与救法 <a class="header-anchor" href="#三、廉价感四因素与救法" aria-label="Permalink to &quot;三、廉价感四因素与救法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>成因</th><th>廉价根源</th><th>Prompt 修复关键词</th></tr></thead><tbody><tr><td>运镜太飘</td><td>镜头像「无重力幽灵」乱窜、加速度异常</td><td><code>Dolly in</code>、<code>Camera Crane</code>、<code>Cinematography</code>、<code>100mm macro</code>、<code>120fps slow motion</code></td></tr><tr><td>打光平</td><td>漫反射过强，无主光/辅光/轮廓光分层</td><td><code>Chiaroscuro</code>、<code>Volumetric rim light</code>、<code>Backlit</code>、<code>Golden hour fill light</code></td></tr><tr><td>材质假</td><td>微观细节丢失，调味粉变贴图、油脂缺乏折射率</td><td><code>Granular texture</code>、<code>Glistening oil droplets</code>、<code>Crystalline texture</code>、<code>Subsurface scattering</code></td></tr><tr><td>色彩失真</td><td>粉末/酱汁缺重力，颜色过饱和</td><td><code>Realistic physics gravity</code>、<code>Cinematic color grading</code>、<code>Volumetric dust</code></td></tr></tbody></table><p><strong>万能避坑公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[主体与微观材质] + [动态物理与动作] + [专业运镜与帧率] + [灯光与明暗] + [色彩与画质风格]</span></span></code></pre></div><p>综合范例（蜂蜜黄油薯条）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Extreme macro shot of golden-brown honey butter french fries, ultra-detailed rough potato texture dusted with fine granular seasoning powder and glistening sugar crystals. A drizzle of liquid honey falls in slow motion (120fps). Smooth motorized dolly-in camera movement. Low-key studio lighting with warm golden rim light and cinematic depth of field. Commercial food styling, dark elegant background.</span></span></code></pre></div><h2 id="四、诊断顺序-迭代控制变量法" tabindex="-1">四、诊断顺序 + 迭代控制变量法 <a class="header-anchor" href="#四、诊断顺序-迭代控制变量法" aria-label="Permalink to &quot;四、诊断顺序 + 迭代控制变量法&quot;">​</a></h2><p>底层逻辑：<strong>先看物理画面是否崩溃，再看镜头是否自然，最后调精细质感</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>画面崩坏度（时长/形变） → 镜头语言（运镜/焦点） → 食品质感（光影/材质） → 品牌氛围（色调/排版）</span></span></code></pre></div><p><strong>第一步：查时长与稳定性（最优先）</strong>——时长超过 10 秒极易中间帧「熔化」「异形」；先把单次生成压到 3~5 秒，动作幅度别太复杂。</p><p><strong>第二步：查运镜与视角</strong>——是否用了 <code>Macro lens</code>、<code>Phantom Flex 4K</code>、<code>120fps</code> 等专业术语，运镜命令是否单一明确。</p><p><strong>第三步：查材质与光影（决定食欲感）</strong>——补 <code>glistening honey glaze</code>、<code>melted butter drizzle</code>、<code>subtle steam rising</code>、<code>backlight / side lighting</code>。</p><p><strong>第四步：查颜色与品牌氛围</strong>——补 <code>Warm lighting</code>、<code>Cinematic commercial color grading</code>。</p><p><strong>迭代时每次只动一处吗？</strong> 原则是「先大改一次，后单点微调」：</p><ul><li><strong>初创阶段（0→1）</strong>：允许同时改 2–3 个核心要素（摄影器材 + 动作 + 光影）。</li><li><strong>精修阶段（1→80 分）</strong>：严格遵守控制变量法，一次只改一个变量——AI 视频随机性高，同时改两个就没法归因。单点微调顺序：先锁主体 → 只调光 → 只调颗粒细节 → 只调镜头速度。</li></ul><table tabindex="0"><thead><tr><th>诊断步骤</th><th>排查重点</th><th>常用提示词</th></tr></thead><tbody><tr><td>稳定度</td><td>截短时长至 3 秒，简化动作</td><td><code>3-second clip, simple motion</code></td></tr><tr><td>运镜</td><td>专业镜头语言与帧率</td><td><code>Macro lens, 120fps slow-motion, Slow push-in</code></td></tr><tr><td>质感</td><td>高光、液体、表面颗粒</td><td><code>Glistening glaze, powder texture, steaming</code></td></tr><tr><td>光影</td><td>背光与广告调色</td><td><code>Studio backlighting, Warm color grading</code></td></tr></tbody></table><hr><p>关联：本文是「片子出问题从哪查起」的诊断入口——单品项写法分别见 <a href="/tools/gemini-video-duration">控制视频时长</a>（第一步）、<a href="/tools/gemini-camera-movement">机位与运镜</a>（第二步）、<a href="/tools/gemini-food-material">食品材质不漂移</a>（第三步）、<a href="/tools/gemini-negative-tokens">排除项写法</a>（负面约束）。</p>',38)])])}const m=e(d,[["render",s]]);export{h as __pageData,m as default};
